namespace {

constexpr int cuda_threads = 256;

template <typename acc_t>
__device__ __forceinline__ bool better_candidate(acc_t candidate_score, int64_t candidate_index, acc_t current_score,
                                                 int64_t current_index) {
    return candidate_index >= 0 && (current_index < 0 || candidate_score > current_score ||
                                    (candidate_score == current_score && candidate_index < current_index));
}

template <typename scalar_t, typename acc_t>
__global__ void soft_nms_class_aware_kernel(int num_boxes, const scalar_t *__restrict__ boxes, int64_t box_row_stride,
                                            int64_t box_column_stride, const scalar_t *__restrict__ scores,
                                            int64_t score_stride, const int64_t *__restrict__ sorted_class_ids,
                                            const int64_t *__restrict__ class_order, acc_t sigma, acc_t score_threshold,
                                            acc_t *__restrict__ working_scores, acc_t *__restrict__ areas,
                                            acc_t *__restrict__ output_scores) {
    const int class_start = static_cast<int>(blockIdx.x);
    if (class_start >= num_boxes ||
        (class_start > 0 && sorted_class_ids[class_start - 1] == sorted_class_ids[class_start])) {
        return;
    }

    __shared__ int class_end;
    __shared__ acc_t reduction_scores[cuda_threads];
    __shared__ int reduction_positions[cuda_threads];
    __shared__ int64_t reduction_indices[cuda_threads];
    __shared__ int continue_processing;
    __shared__ acc_t selected_box[4];
    __shared__ acc_t selected_area;

    if (threadIdx.x == 0) {
        const int64_t class_id = sorted_class_ids[class_start];
        class_end = class_start + 1;
        while (class_end < num_boxes && sorted_class_ids[class_end] == class_id) {
            ++class_end;
        }
    }
    __syncthreads();

    const acc_t negative_infinity = -std::numeric_limits<acc_t>::infinity();
    for (int position = class_start + static_cast<int>(threadIdx.x); position < class_end;
         position += static_cast<int>(blockDim.x)) {
        const int64_t input_index = class_order[position];
        const acc_t score = static_cast<acc_t>(scores[input_index * score_stride]);
        working_scores[position] = score > score_threshold ? score : negative_infinity;

        const scalar_t *box = boxes + input_index * box_row_stride;
        const acc_t width =
            static_cast<acc_t>(box[2 * box_column_stride]) - static_cast<acc_t>(box[0 * box_column_stride]);
        const acc_t height =
            static_cast<acc_t>(box[3 * box_column_stride]) - static_cast<acc_t>(box[1 * box_column_stride]);
        areas[position] = width * height;
    }
    __syncthreads();

    while (true) {
        acc_t best_score = negative_infinity;
        int best_position = -1;
        int64_t best_index = -1;
        for (int position = class_start + static_cast<int>(threadIdx.x); position < class_end;
             position += static_cast<int>(blockDim.x)) {
            const acc_t candidate_score = working_scores[position];
            const int64_t candidate_index = class_order[position];
            if (candidate_score > score_threshold &&
                better_candidate(candidate_score, candidate_index, best_score, best_index)) {
                best_score = candidate_score;
                best_position = position;
                best_index = candidate_index;
            }
        }

        reduction_scores[threadIdx.x] = best_score;
        reduction_positions[threadIdx.x] = best_position;
        reduction_indices[threadIdx.x] = best_index;
        __syncthreads();

        for (int offset = cuda_threads / 2; offset > 0; offset /= 2) {
            if (threadIdx.x < offset &&
                better_candidate(reduction_scores[threadIdx.x + offset], reduction_indices[threadIdx.x + offset],
                                 reduction_scores[threadIdx.x], reduction_indices[threadIdx.x])) {
                reduction_scores[threadIdx.x] = reduction_scores[threadIdx.x + offset];
                reduction_positions[threadIdx.x] = reduction_positions[threadIdx.x + offset];
                reduction_indices[threadIdx.x] = reduction_indices[threadIdx.x + offset];
            }
            __syncthreads();
        }

        if (threadIdx.x == 0) {
            const int selected_position = reduction_positions[0];
            continue_processing = selected_position >= 0;
            if (continue_processing != 0) {
                const int64_t selected_index = reduction_indices[0];
                const scalar_t *box = boxes + selected_index * box_row_stride;
                selected_box[0] = static_cast<acc_t>(box[0 * box_column_stride]);
                selected_box[1] = static_cast<acc_t>(box[1 * box_column_stride]);
                selected_box[2] = static_cast<acc_t>(box[2 * box_column_stride]);
                selected_box[3] = static_cast<acc_t>(box[3 * box_column_stride]);
                selected_area = areas[selected_position];
                output_scores[selected_index] = reduction_scores[0];
                working_scores[selected_position] = negative_infinity;
            }
        }
        __syncthreads();

        if (continue_processing == 0) {
            return;
        }

        for (int position = class_start + static_cast<int>(threadIdx.x); position < class_end;
             position += static_cast<int>(blockDim.x)) {
            const acc_t score = working_scores[position];
            if (score <= score_threshold) {
                continue;
            }

            const int64_t input_index = class_order[position];
            const scalar_t *box = boxes + input_index * box_row_stride;
            const acc_t x1 = static_cast<acc_t>(box[0 * box_column_stride]);
            const acc_t y1 = static_cast<acc_t>(box[1 * box_column_stride]);
            const acc_t x2 = static_cast<acc_t>(box[2 * box_column_stride]);
            const acc_t y2 = static_cast<acc_t>(box[3 * box_column_stride]);

            const acc_t intersection_x1 = selected_box[0] > x1 ? selected_box[0] : x1;
            const acc_t intersection_y1 = selected_box[1] > y1 ? selected_box[1] : y1;
            const acc_t intersection_x2 = selected_box[2] < x2 ? selected_box[2] : x2;
            const acc_t intersection_y2 = selected_box[3] < y2 ? selected_box[3] : y2;
            const acc_t intersection_width = intersection_x2 > intersection_x1 ? intersection_x2 - intersection_x1 : 0;
            const acc_t intersection_height = intersection_y2 > intersection_y1 ? intersection_y2 - intersection_y1 : 0;
            const acc_t intersection = intersection_width * intersection_height;

            acc_t iou = 0;
            if (intersection > 0) {
                const acc_t union_area = selected_area + areas[position] - intersection;
                iou = intersection / (union_area + static_cast<acc_t>(1e-8));
            }

            const acc_t updated_score = score * exp(-(iou * iou) / sigma);
            working_scores[position] = updated_score > score_threshold ? updated_score : negative_infinity;
        }
        __syncthreads();
    }
}

} // namespace

std::tuple<at::Tensor, at::Tensor> soft_nms_cuda(const at::Tensor &boxes, const at::Tensor &scores,
                                                 const at::Tensor &class_ids, double sigma, double score_threshold) {
    at::DeviceGuard guard(boxes.device());

    TORCH_CHECK(boxes.dim() == 2 && boxes.size(1) == 4, "boxes must have shape (N, 4)");
    TORCH_CHECK(scores.dim() == 1 && scores.size(0) == boxes.size(0), "scores must have shape (N,) matching boxes");
    TORCH_CHECK(class_ids.dim() == 1 && class_ids.size(0) == boxes.size(0),
                "class_ids must have shape (N,) matching boxes");
    TORCH_CHECK(boxes.is_floating_point() && scores.is_floating_point(), "boxes and scores must be floating-point");
    TORCH_CHECK(boxes.scalar_type() == scores.scalar_type(), "boxes and scores must have the same dtype");
    TORCH_CHECK(class_ids.scalar_type() == c10::ScalarType::Long, "class_ids must have dtype int64");
    TORCH_CHECK(boxes.device() == scores.device() && boxes.device() == class_ids.device(),
                "boxes, scores and class_ids must be on the same device");
    TORCH_CHECK(sigma > 0, "sigma must be positive");
    TORCH_CHECK(boxes.size(0) <= std::numeric_limits<int>::max(), "number of boxes exceeds the CUDA kernel limit");

    const int num_boxes = static_cast<int>(boxes.size(0));
    if (num_boxes == 0) {
        return std::make_tuple(at::empty({0}, scores.options()), at::empty({0}, class_ids.options()));
    }

    at::Tensor sorted_class_ids;
    at::Tensor class_order;
    std::tie(sorted_class_ids, class_order) = at::sort(class_ids, 0, false);

    const c10::ScalarType accumulation_type =
        scores.scalar_type() == c10::ScalarType::Half || scores.scalar_type() == c10::ScalarType::BFloat16
            ? c10::ScalarType::Float
            : scores.scalar_type();
    const auto accumulation_options = scores.options().dtype(accumulation_type);
    at::Tensor working_scores = at::empty({num_boxes}, accumulation_options);
    at::Tensor areas = at::empty({num_boxes}, accumulation_options);
    at::Tensor output_scores = at::full({num_boxes}, -std::numeric_limits<double>::infinity(), accumulation_options);

    const at::cuda::CUDAStream stream = at::cuda::getCurrentCUDAStream();
    AT_DISPATCH_FLOATING_TYPES_AND2(
        at::ScalarType::Half, at::ScalarType::BFloat16, scores.scalar_type(), "soft_nms_class_aware_cuda", ([&] {
            using acc_t = at::acc_type<scalar_t, true>;
            soft_nms_class_aware_kernel<scalar_t, acc_t><<<num_boxes, cuda_threads, 0, stream.stream()>>>(
                num_boxes, boxes.data_ptr<scalar_t>(), boxes.stride(0), boxes.stride(1), scores.data_ptr<scalar_t>(),
                scores.stride(0), sorted_class_ids.data_ptr<int64_t>(), class_order.data_ptr<int64_t>(),
                static_cast<acc_t>(sigma), static_cast<acc_t>(score_threshold), working_scores.data_ptr<acc_t>(),
                areas.data_ptr<acc_t>(), output_scores.data_ptr<acc_t>());
            C10_CUDA_KERNEL_LAUNCH_CHECK();
        }));

    at::Tensor sorted_scores;
    at::Tensor keep;
    std::tie(sorted_scores, keep) = at::sort(output_scores, std::optional<bool>(true), 0, true);
    const at::Tensor score_mask = at::gt(sorted_scores, score_threshold);
    sorted_scores = at::masked_select(sorted_scores, score_mask).to(scores.scalar_type());
    keep = at::masked_select(keep, score_mask);
    return std::make_tuple(sorted_scores, keep);
}
